package gg.hera.features;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class CompanionAnimationMathTest {
 @Test void animationSamplingInterpolatesAndClamps(){float[][] frames={{0,10,20},{2,20,40},{4,30,60}};assertEquals(1,CompanionAnimationMath.sample(frames,1/120d,0));assertEquals(0,CompanionAnimationMath.sample(frames,-1,0));assertEquals(4,CompanionAnimationMath.sample(frames,10000,0));assertEquals(10,CompanionAnimationMath.sample(frames,Double.NaN,1));}
 @Test void clipTransitionsUseTheShortestAngleAcrossWrap(){assertEquals(360,CompanionAnimationMath.angle(359,1,.5f));assertEquals(-180,CompanionAnimationMath.angle(-170,170,.5f));assertEquals(2,CompanionAnimationMath.blend(0,8,.25f));assertEquals(0,CompanionAnimationMath.transition(0,0,4));assertEquals(.5f,CompanionAnimationMath.transition(2,0,4));assertEquals(1,CompanionAnimationMath.transition(20,0,4));assertEquals(1,CompanionAnimationMath.transition(0,0,0));}
 @Test void glowAndBlendDefaultsAndInvalidOptionsStayBounded(){var o=new com.google.gson.Gson().fromJson("{}",ModuleOptions.class);assertTrue(o.companionGlow);assertFalse(o.companionHideWithHud);assertEquals(4,o.companionBlend);assertTrue(o.itemPhysicsFlat);assertFalse(o.itemMirrorLeft);o.companionBlend=200;o.legacyStrength=Float.NaN;o.itemPhysicsSpeed=-10;o.nametagRange=500;o.normalize();assertEquals(10,o.companionBlend);assertEquals(1,o.legacyStrength);assertEquals(0,o.itemPhysicsSpeed);assertEquals(64,o.nametagRange);}
 @Test void nearestDyeIgnoresAlphaAndKeepsStableTies(){int[] palette={0x000000,0xFFFFFF,0xFF0000};assertEquals(2,ColorMatch.nearest(0x22F00000,palette));assertEquals(0,ColorMatch.nearest(0x010101,palette));assertEquals(0,ColorMatch.nearest(0,new int[]{0,0}));assertEquals(-1,ColorMatch.nearest(0,new int[0]));}
 @Test void cachedZyxOrientationMatchesThePreviousSequentialRotations(){for(float[] degrees:new float[][]{{0,0,0},{30,-50,85},{-170,170,270}}){float x=(float)Math.toRadians(degrees[0]),y=(float)Math.toRadians(degrees[1]),z=(float)Math.toRadians(degrees[2]);var sequential=new org.joml.Matrix4f().rotateZ(z).rotateY(y).rotateX(x);var cached=new org.joml.Matrix4f().rotation(new org.joml.Quaternionf().rotationZYX(z,y,x));assertArrayEquals(sequential.get(new float[16]),cached.get(new float[16]),.00001f);}}
 @Test void initialPoseNeverFallsBackIntoAnUninitializedBlend(){var transition=new CompanionPoseTransition();assertEquals(1,transition.update(1,1,0,0,4));assertFalse(transition.capturePrevious());assertEquals(1,transition.update(1,1,0,.8f,4));assertEquals(1,transition.update(1,1,1,0,4));}
 @Test void rapidChangesCaptureLastShownPoseAndWorldResetDropsOldPose(){var transition=new CompanionPoseTransition();transition.update(1,1,0,0,4);assertEquals(0,transition.update(1,2,0,0,4));assertTrue(transition.capturePrevious());assertEquals(.5f,transition.update(1,2,2,0,4));assertFalse(transition.capturePrevious());assertEquals(0,transition.update(1,3,0,0,4));assertTrue(transition.capturePrevious());assertEquals(1,transition.update(2,3,0,0,4));assertFalse(transition.capturePrevious());transition.reset();assertEquals(1,transition.update(2,3,0,0,4));}
}
